  </style>
</head>
<body>
  <div id="maze"></div>
  <div class="controls">
    <button onclick="moveCharacter('up')">Up</button>
    <button onclick="moveCharacter('down')">Down</button>
    <button onclick="moveCharacter('left')">Left</button>
    <button onclick="moveCharacter('right')">Right</button>
  </div>
  <script>
    const mazeSize = 4;
    let mazeLayout = [];
    let characterPosition = { row: 0, col: 0 };
    class SeededRNG {
      constructor(seed) { this.seed = seed; }
      random() {
        const a = 1664525, c = 1013904223, m = 2**32;
        this.seed = (a * this.seed + c) % m;
        return this.seed / m;
      }
    }
    rng = new SeededRNG(1104996223);
    function generateMaze() {
      mazeLayout = [];
      for (let row = 0; row < mazeSize; row++) {
        const currentRow = [];
        for (let col = 0; col < mazeSize; col++) { currentRow.push('#'); }
        mazeLayout.push(currentRow);
      }
      const stack = [{ row: 0, col: 0 }];
      const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
      while (stack.length > 0) {
        const { row, col } = stack.pop();
        mazeLayout[row][col] = ' ';
        if (row === mazeSize - 1 && col === mazeSize - 1) break;
        for (let i = directions.length - 1; i > 0; i--) {
          const j = Math.floor(rng.random() * (i + 1));
          [directions[i], directions[j]] = [directions[j], directions[i]];
        }
        for (const [dx, dy] of directions) {
          const newRow = row + dx, newCol = col + dy;
          if (newRow >= 0 && newRow < mazeSize && newCol >= 0 && newCol < mazeSize && mazeLayout[newRow][newCol] === '#') {
            stack.push({ row: newRow, col: newCol });
          }
        }
      }
      mazeLayout[0][0] = ' ';
      mazeLayout[mazeSize - 1][mazeSize - 1] = '$';
      characterPosition = { row: 0, col: 0 };
    }
    function renderMaze() {
      const mazeElement = document.getElementById('maze');
      mazeElement.innerHTML = '';
      for (let row = 0; row < mazeLayout.length; row++) {
        const rowElement = document.createElement('div');
        rowElement.className = 'row';
        for (let col = 0; col < mazeLayout[row].length; col++) {
          const cellElement = document.createElement('div');
          cellElement.className = 'cell';
          if (mazeLayout[row][col] === '#') { cellElement.classList.add('wall'); }
          else if (row === characterPosition.row && col === characterPosition.col) { cellElement.classList.add('character'); cellElement.innerHTML = 'X'; }
          else if (mazeLayout[row][col] === '$') { cellElement.classList.add('goal'); }
          rowElement.appendChild(cellElement);
        }
        mazeElement.appendChild(rowElement);
      }
    }
    function moveCharacter(direction) {
      const newPosition = { ...characterPosition };
      switch (direction) {
        case 'up': newPosition.row--; break;
        case 'down': newPosition.row++; break;
        case 'left': newPosition.col--; break;
        case 'right': newPosition.col++; break;
      }
      if (isValidMove(newPosition)) {
        characterPosition = newPosition;
        renderMaze();
        checkGoalReached();
      }
    }
    function isValidMove(position) {
      const { row, col } = position;
      if (row < 0 || row >= mazeLayout.length || col < 0 || col >= mazeLayout[row].length || mazeLayout[row][col] === '#') return false;
      return true;
    }
    function checkGoalReached() {
      const { row, col } = characterPosition;
      if (mazeLayout[row][col] === '$') { document.body.innerHTML = '<h1>Success!</h1>'; }
    }
    function solveMaze() {
      const goal = { row: mazeSize-1, col: mazeSize-1 };
      const queue = [[{row:0,col:0}]];
      const visited = new Set(['0,0']);
      while (queue.length > 0) {
        const path = queue.shift();
        const {row, col} = path[path.length-1];
        if (row === goal.row && col === goal.col) {
          const moves = [];
          for (let i = 1; i < path.length; i++) {
            const pr = path[i-1].row, pc = path[i-1].col;
            const nr = path[i].row, nc = path[i].col;
            if (nr === pr+1) moves.push('down');
            else if (nr === pr-1) moves.push('up');
            else if (nc === pc+1) moves.push('right');
            else moves.push('left');
          }
          return moves;
        }
        for (const [dr, dc] of [[-1,0],[1,0],[0,-1],[0,1]]) {
          const nr = row+dr, nc = col+dc;
          const key = nr+','+nc;
          if (nr>=0 && nr<mazeSize && nc>=0 && nc<mazeSize && !visited.has(key) && mazeLayout[nr][nc] !== '#') {
            visited.add(key);
            queue.push([...path, {row:nr,col:nc}]);
          }
        }
      }
      return [];
    }
    generateMaze();
    renderMaze();
    var autoMoves = solveMaze();
    var moveIndex = 0;
    function autoSolve() {
      if (moveIndex < autoMoves.length) {
        moveCharacter(autoMoves[moveIndex]);
        moveIndex++;
        setTimeout(autoSolve, 500);
      }
    }
    setTimeout(autoSolve, 1000);
  </script>
</body>
</html>
